def _leitura(trecho, nome, quando=None, rotulo="INPUT do operador"):
    assert trecho in TEXTOS[S16(nome)], ("a leitura do operador NAO esta verbatim na fala", nome, trecho)
    q_ = quando or ("30/10/2026" if "_30out_" in nome else "31/10/2026" if "_31out_" in nome else "01/11/2026")
    return {"trecho": trecho, "estatuto": "[%s, verbatim %s, sha16 %s]" % (rotulo, q_, S16(nome))}


