def contrato(stone, fj, formal_map, e_base, base_sha256, core0=None, alpha_runtime=None):
    """O contrato de UMA pedra (as falas ficam em _V405_VERBATINS2), DERIVADO do build do sandbox (FLAGS_v405.json = nomes, chaves e a proveniencia dos termos de suporte; formal_map = sha256 das fontes embutidas; e_base = a escada da v404 selada;
    a escada esperada e' a DESTA versao: a da base + as bandeiras das OITO pedras); nada digitado. core0 = o core da v404 SELADA, de onde saem os pinos do canal do neutrino. Vai para CANDIDATO_v405.json e ESPERADOS_v405.json."""
    k = stone["key"]
    flag_de = {n: f for f, n, m, o in fj["flags"]}
    faltam = [t for t in stone["contract"] if t not in flag_de]
    assert not faltam, ("teorema do contrato sem bandeira (nao nomeado ou ausente do Audit)", k, faltam[:5])
    assert fj["bandeira_do_teorema_incondicional"][k] == flag_de[stone["theorem"]] and fj["teorema_incondicional"][k] == stone["theorem"]
    assert stone["key_theorem"] in stone["contract"] and stone["theorem"] in stone["contract"]
    sup = dict(fj["suporte_do_contrato"][k]); assert sup == dict(stone["support"]), "os termos de suporte do FLAGS_v405.json diferem dos de delta_v405: " + k
    cit = dict(fj["citados_fora_do_contrato"][k]); assert cit == dict(stone["citados_fora"]), "os termos citados-fora do FLAGS_v405.json diferem dos de delta_v405: " + k
    nm0 = (core0 or {}).get("neutrino_mass") or {}
    assert str(nm0.get("angle_status", "")).startswith(DL.ANGLE_STATUS_ANTIGO_PREFIXO), "o angle_status da base (v404 selada) NAO comeca como a v405 espera (a errata ao lado cita o texto antigo)"
    c = {"stone": {"path": stone["rel"], "sha256": formal_map[stone["rel"]], "module": stone["mod"]}, "nome_do_operador": stone["nome_do_operador"],
         "unconditional": {"theorem": stone["theorem"], "flag": flag_de[stone["theorem"]]},
         "key_theorem": {"theorem": stone["key_theorem"], "flag": flag_de[stone["key_theorem"]]}, "key_statement": KEY_STATEMENT[k],
         "theorems": {t: flag_de[t] for t in stone["contract"]}, "support": sup, "cited_outside": cit,
         "auxiliaries_outside_the_composition": list(stone["auxiliares_fora_da_composicao"]), "context": dict(CONTEXTO[k]), "named_hypotheses_in_the_statement": stone["hipoteses_no_enunciado"],
         "expected_ladder": e_base + fj["n_flags"], "n_flags": fj["nomeadas_por_pedra"][k], "n_flags_total": fj["n_flags"], "verbatins": list(VERBATINS_DO_REGISTRO[k]), "baseline": {"version": DL.BASE_VERSION, "sha256": base_sha256},
         "constants": dict(CONSTANTES, alpha_runtime=alpha_runtime), "modulos_novos": list(DL.STONE_RELS),
         "neutrino": {"angle_status_antigo_prefixo": DL.ANGLE_STATUS_ANTIGO_PREFIXO, "angle_status_antigo_sha256": __import__("hashlib").sha256(nm0["angle_status"].encode("utf-8")).hexdigest(), "frozen_hash_v404": nm0["frozen_hash"], "m_nu_meV_v404": nm0["m_nu_meV"], "verdict_v404": nm0["verdict"]}}
    return c


